#define F(x) feat[x]
void print_feat(float *feat)
{
    printf("%f, %f, %f, %f, %f, %f, %f, %f, %f, %f, %f, %f\n",
           F(0), F(1), F(2), F(100), F(101), F(102),
           F(1000), F(1001), F(1002), F(1917), F(1918), F(1919));
}
#undef F

int main()
{
    float feat[kFeatNum];

    dl::audio::SpeechFeatureConfig config;
    config.frame_length = FBANK_FO_FLM;
    config.frame_shift = FBANK_FO_FSM;
    config.num_mel_bins = FBANK_MEL_NUM;
    config.preemphasis = 0.97f;
    config.low_freq = 20.0f;                      /*!< Lower edge of mel filters */
    config.high_freq = 0.0f;                   /*!< Upper edge of mel filters */

    config.use_log_fbank = 1;
    config.raw_energy = false;
    config.use_energy = false;
    config.use_int16_fft = true;
    config.remove_dc_offset = true;
    config.window_type = dl::audio::WinType::POVEY;

    dl::audio::Fbank fbank(config);

    int ret = fbank.process(wav1, kNumSamples, feat);
    printf("fbank process ret:%d\n", ret);

    // result -15.942385, -15.942385, -15.942385, -15.942385, -15.942385, -15.942385, 11.287176, 11.515824, 11.411964, 8.452115, 8.320729, 7.054681
    print_feat(feat);

    //dl::audio::Fbank fbank1(config);
    ret = fbank.process(wav3, kNumSamples, feat);
    printf("fbank process ret:%d\n", ret);

    // 7.799166, 7.130743, 7.596199, 8.398475, 9.300026, 10.773014, 10.253153, 9.757631, 10.224535, 8.408671, 8.569152, 7.832201
    print_feat(feat);

    return 0;
}